steps.cmd:
python - <<'PY'
import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot(timeout=10);o=r.get_obs(depth=True,video='none')
xyz=np.array(o.meta['proprio']['now'][8:11]); print('tcp',xyz)
for c in ['egocentric_mirrored_camera','over_shoulder_left_camera']:
 K=np.array(o.meta['cameras'][c]['intrinsic_cv']);E=np.array(o.meta['cameras'][c]['extrinsic_cv']);
 def proj(p):
  pc=E[:,:3]@np.array(p)+E[:,3]; return np.array([K[0,0]*pc[0]/pc[2]+K[0,2],K[1,1]*pc[1]/pc[2]+K[1,2],pc[2]])
 print(c)
 for name,p in [('tcp',xyz),('targettop',np.r_[.527,.196,.053]),('largeTop',np.r_[.625,.237,.058]),('smallassumed',np.r_[.49,.227,.05]),('pumpkinDown',np.r_[.527,.196,.025])]: print(name,proj(p).round(1))
PY

