def send_path(r, name, target, grip, hold=0, quat=Q_DOWN):
    """Follow a short IK waypoint path with the joint-position stream controller."""
    obs = r.get_obs(video="none")
    now = np.asarray(obs.meta["proprio"]["now"], dtype=float)
    start = now[8:11]
    seed = now[:7].copy()
    target = np.asarray(target, dtype=float)
    count = max(1, int(math.ceil(np.linalg.norm(target - start) / MAX_STEP)))
    xyz = [start + (target - start) * (i / count) for i in range(1, count + 1)]
    rows = []
    for p in xyz:
        ik = r.ik({"tcp": np.r_[p, quat]}, seed=seed)
        if not ik.get("ok"):
            raise RuntimeError(f"{name}: IK failed at {p.tolist()}: {ik}")
        seed = np.asarray(ik["q"], dtype=float)
        rows.append(np.r_[seed, float(grip)])
    if hold:
        rows.extend([np.r_[seed, float(grip)]] * hold)
    if len(rows) * JOINT_DT > 10.0:
        raise ValueError(f"{name}: {len(rows)} rows exceed the 10 s joint-position chunk limit")
    res = r.submit("joint_position", np.asarray(rows, dtype=np.float32), dt=JOINT_DT,
                   video="none", note=name)
    folder = OUT / f"trace_{name}"
    res.save(str(folder))
    plans = res.meta.get("plan", [])
    print(json.dumps({
        "stage": name,
        "rows": len(rows),
        "executed": res.meta.get("executed_rows"),
        "control_steps_chunk": res.meta.get("control_steps_chunk"),
        "done": res.meta.get("done"),
        "reason": res.meta.get("reason"),
        "plan_count": len(plans) if isinstance(plans, list) else None,
        "plan_tail": plans[-2:] if isinstance(plans, list) else plans,
        "tcp_now": res.meta.get("proprio", {}).get("now", [])[8:15],
        "saved": str(folder),
    }), flush=True)
    return res


